// ── JSON ─────────────────────────────────────────────────────────────────────

/// A field no message of the API has, and an enum's name no enum of it has.
const LATER_FIELD: &str = "a_later_field";
const LATER_NAME: &str = "A_LATER_NAME";

/// Every copy of `json` with one more field, in one of the objects it is made of.
fn with_a_later_field(json: &Value) -> Vec<Value> {
    /// `json` with `inner` where it has `key`.
    fn with<Key: serde_json::value::Index>(json: &Value, key: Key, inner: Value) -> Value {
        let mut copy = json.clone();
        copy[key] = inner;
        copy
    }

    match json {
        Value::Object(fields) => {
            let deeper = fields.iter().flat_map(|(name, value)| {
                let copies = with_a_later_field(value).into_iter();
                copies.map(move |inner| with(json, name, inner))
            });
            std::iter::once(with(json, LATER_FIELD, Value::from(1)))
                .chain(deeper)
                .collect()
        }
        Value::Array(items) => {
            let deeper = items.iter().enumerate().flat_map(|(place, item)| {
                let copies = with_a_later_field(item).into_iter();
                copies.map(move |inner| with(json, place, inner))
            });
            deeper.collect()
        }
        _ => Vec::new(),
    }
}

/// `json` with each 64-bit integer in it as a number, the other form the API takes one in.
/// JSON writes one as a string of digits, and no sample has such a text.
fn with_wide_numbers(json: &Value) -> Value {
    match json {
        Value::String(digits) => match (digits.parse::<u64>(), digits.parse::<i64>()) {
            (Ok(number), _) => Value::from(number),
            (_, Ok(number)) => Value::from(number),
            _ => json.clone(),
        },
        Value::Array(items) => items.iter().map(with_wide_numbers).collect(),
        Value::Object(fields) => {
            let fields = fields
                .iter()
                .map(|(name, value)| (name.clone(), with_wide_numbers(value)));
            fields.collect()
        }
        _ => json.clone(),
    }
}

/// A message at every `k`, as `public` and as `wire` have it, through JSON:
///
/// - written, it is the wire layer's JSON of the same sample, and an `Unrecognized` member of
///   a oneof is no member;
/// - its fields are under `names`, the proto's, each at some `k`, and under no other;
/// - read back, it is the sample, with its 64-bit integers as numbers too;
/// - with a field the API does not have, in any object of it, it is refused by that name;
/// - a list is refused: the wire layer would take one as a message's fields in their order.
fn a_message_is_json<Public, Wire>(
    states: usize,
    names: &[&str],
    public: fn(usize, bool) -> Public,
    wire: fn(usize, bool) -> Wire,
) where
    Public: Serialize + DeserializeOwned + PartialEq + std::fmt::Debug,
    Wire: Serialize,
{
    let mut written = BTreeSet::new();

    for k in 0..states {
        let json = serde_json::to_value(wire(k, false)).unwrap();
        assert_eq!(serde_json::to_value(public(k, true)).unwrap(), json, "at k = {k}");
        assert_eq!(
            serde_json::from_value::<Public>(json.clone()).unwrap(),
            public(k, false),
            "at k = {k}"
        );
        assert_eq!(
            serde_json::from_value::<Public>(with_wide_numbers(&json)).unwrap(),
            public(k, false),
            "at k = {k}"
        );

        written.extend(json.as_object().unwrap().keys().cloned());
        for later in with_a_later_field(&json) {
            let refusal = serde_json::from_value::<Public>(later).unwrap_err().to_string();
            assert!(refusal.contains(LATER_FIELD), "at k = {k}: {refusal}");
        }
    }

    let names: BTreeSet<String> = names.iter().map(|name| name.to_string()).collect();
    assert_eq!(written, names);
    assert!(
        serde_json::from_value::<Public>(Value::Array(Vec::new())).is_err(),
        "a list was read as the message"
    );
}

/// An enum through JSON: each value is its name in the proto, and a number this version has
/// no name for is the number, both ways. A name it does not know is refused.
fn an_enum_is_json<Public>(names: &[&str], later: i32, sample: fn(usize) -> Public)
where
    Public: Serialize + DeserializeOwned + PartialEq + std::fmt::Debug,
{
    let forms = names.iter().map(|name| Value::from(*name)).chain([Value::from(later)]);

    for (k, json) in forms.enumerate() {
        assert_eq!(serde_json::to_value(sample(k)).unwrap(), json);
        assert_eq!(serde_json::from_value::<Public>(json).unwrap(), sample(k));
    }
    assert!(serde_json::from_value::<Public>(Value::from(LATER_NAME)).is_err());
}

