/// A time's JSON is RFC 3339, to the nanosecond, both ways.
#[test]
fn a_time_is_json() {
    let time = Timestamp {
        seconds: 1_791_279_000,
        nanos: 1,
    };
    let json = Value::from("2026-10-06T09:30:00.000000001Z");

    assert_eq!(serde_json::to_value(time).unwrap(), json);
    assert_eq!(serde_json::from_value::<Timestamp>(json).unwrap(), time);
}

// ── Streams ──────────────────────────────────────────────────────────────────

/// A stream as a call: its first response, or the error that ended it. It reads by `next`.
///
/// A stream that yields none stands for the response with nothing set. On the wire that one is
/// the API's pulse, which a stream passes over, so a fake that answers with it alone has said
/// nothing; what a stream makes of pulses is `a_stream_is_read`'s to see.
async fn first<T: Default>(mut responses: ResponseStream<T>) -> Result<T, Error> {
    let mut first = None;
    while let Some(response) = responses.next().await {
        first.get_or_insert(response?);
    }
    Ok(first.unwrap_or_default())
}

/// The next item of a stream, read as a `Stream` of the `futures` crates is.
async fn polled<T>(responses: &mut ResponseStream<T>) -> Option<Result<T, Error>> {
    std::future::poll_fn(|context| futures_core::Stream::poll_next(Pin::new(&mut *responses), context)).await
}

/// Every item of a stream, to its end and one read past it.
async fn items<T>(mut responses: ResponseStream<T>) -> Vec<Result<T, Error>> {
    let mut items = Vec::new();
    while let Some(item) = polled(&mut responses).await {
        items.push(item);
        assert!(
            items.len() < 100,
            "the stream yields on and on: the fake sends a few responses"
        );
    }
    assert!(
        polled(&mut responses).await.is_none(),
        "a stream that ended yields again"
    );
    items
}

/// A stream's method, through each way a stream goes. `open` calls it, and `sample` is its
/// response at `k`: as the fake sends it, and as the method must yield it.
async fn a_stream_is_read<Request, Wire, Response, Open>(
    rpc: &str,
    open: Open,
    sample: impl Fn(usize) -> (Wire, Response),
) where
    Request: buffa::Message,
    Wire: buffa::Message + Default,
    Response: PartialEq + std::fmt::Debug,
    Open: Fn(Client) -> ResponseStream<Response> + Copy,
{
    // Three responses that each say something: what the fake sends at an odd `k` carries a
    // field. And the API's pulse, the response with nothing set that it sends through a
    // silence: on the wire, a message of no bytes.
    let (said, expected): (Vec<Wire>, Vec<Response>) = [1, 3, 5].into_iter().map(sample).unzip();
    let pulse = Wire::default();
    assert!(
        pulse.encode_to_vec().is_empty(),
        "a response with nothing set has bytes on the wire"
    );

    // What the fake sends: a pulse before each response, and one after the last.
    let sent: Vec<Wire> = said
        .iter()
        .flat_map(|response| [pulse.clone(), response.clone()])
        .chain([pulse.clone()])
        .collect();
    let all = |client| items(open(client));
    let responses = |items: Vec<Result<Response, Error>>| items.into_iter().map(Result::unwrap).collect::<Vec<_>>();

    // A stream that ends by itself: each response, in the API's order, no pulse among them, and
    // no error.
    let (_, got): (Request, _) = exchange(rpc, streamed(&sent, End::Clean), all).await;
    assert_eq!(responses(got), expected);

    // One the API had nothing to say in, to its end: nothing, and no error.
    let silence = [pulse.clone(), pulse];
    let (_, got): (Request, _) = exchange(rpc, streamed(&silence, End::Clean), all).await;
    assert!(got.is_empty(), "a stream of pulses alone yielded {got:?}");

    // One that fails midway: the responses that came before, then the error, once.
    let failed = error(
        "out_of_range",
        &[("pethost.panel.v1.ProjectBusy", b"")],
        &STANDARD_NO_PAD,
    );
    let (_, mut got): (Request, _) = exchange(rpc, streamed(&sent, End::Failed(failed)), all).await;
    let last = got.pop().expect("a stream that failed yielded nothing").unwrap_err();
    assert_eq!(
        (last.code(), last.message(), last.details().len()),
        (ErrorCode::OutOfRange, MESSAGE, 1)
    );
    assert_eq!(responses(got), expected);

    // A call the API refuses: a stream of no response that ends with the error, which is the
    // error alone.
    let refused = error("not_found", &[], &STANDARD_NO_PAD);
    let (_, got): (Request, _) = exchange(rpc, streamed(&sent[..0], End::Failed(refused)), all).await;
    let [Err(only)] = got.as_slice() else {
        panic!("a refused call yielded {got:?}")
    };
    assert_eq!((only.code(), only.message()), (ErrorCode::NotFound, MESSAGE));

    // A caller that leaves a stream that goes on. Each response came as the API sent it, the
    // last one too, not held back for a next one or for the stream's end; and the fake, which
    // waits for its caller to leave, saw it leave, or `exchange` would not return.
    let count = expected.len();
    let leave = |client| async move {
        let mut responses = open(client);
        let mut came = Vec::new();
        for _ in 0..count {
            match tokio::time::timeout(SOON, responses.next()).await {
                Ok(Some(item)) => came.push(item),
                _ => break,
            }
        }
        came
    };
    let (_, got): (Request, _) = exchange(rpc, streamed(&sent, End::Open), leave).await;
    assert_eq!(
        responses(got),
        expected,
        "what the API sent did not all come while the stream went on"
    );
}

/// The API may say nothing of a stream before its first response, as beside a quiet log: a
/// caller that leaves then ends its call as well.
#[tokio::test]
async fn a_stream_left_before_the_apis_first_word_ends_its_call() {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let client = Client::with_base_url(TOKEN, &format!("http://{address}")).unwrap();

    let fake = tokio::spawn(take(listener));

    // Reading makes the call; the fake takes its request, and answers nothing.
    let mut responses = client.watch_operation(types::WatchOperationRequest::default());
    let taken = tokio::select! {
        taken = fake => taken.unwrap(),
        item = responses.next() => panic!("the fake said nothing, and the stream yielded {item:?}"),
    };

    drop(responses);
    tokio::time::timeout(SOON, taken.unanswered())
        .await
        .expect("the API still has the caller that left its stream");
}

#[tokio::test]
async fn watch_operation_is_a_stream() {
    let open = |client: Client| client.watch_operation(types::WatchOperationRequest::default());
    let sample = |k| {
        (
            on_wire::watch_operation_response(k, true),
            samples::watch_operation_response(k, true),
        )
    };

    a_stream_is_read::<wire::WatchOperationRequest, _, _, _>("WatchOperation", open, sample).await;
}

